def ticket_price(age):
    if age < 12:
        return 5
    if age >= 65:
        return 7
    return 10

def digit_sum(n):
    total = 0
    while n > 0:
        total += n % 10
        n //= 10
    return total

def unique_in_order(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

def word_frequency(text):
    counts = {}
    for word in text.lower().split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def group_by_first_letter(words):
    groups = {}
    for word in words:
        letter = word[0].lower()
        if letter not in groups:
            groups[letter] = []
        groups[letter].append(word)
    for letter in groups:
        groups[letter] = sorted(groups[letter])
    return groups

def caesar_shift(text, shift):
    result = ""
    for char in text:
        if "a" <= char <= "z":
            result += chr((ord(char) - ord("a") + shift) % 26 + ord("a"))
        elif "A" <= char <= "Z":
            result += chr((ord(char) - ord("A") + shift) % 26 + ord("A"))
        else:
            result += char
    return result

def to_int_list(tokens):
    values = []
    errors = 0
    for token in tokens:
        try:
            values.append(int(token))
        except ValueError:
            errors += 1
    return {"values": values, "errors": errors}

from datetime import date


def days_until(today, deadline):
    try:
        start = date.fromisoformat(today)
        end = date.fromisoformat(deadline)
    except ValueError:
        return None
    if end < start:
        return 0
    return (end - start).days

def flatten(nested):
    result = []
    for item in nested:
        if isinstance(item, list):
            result += flatten(item)
        else:
            result.append(item)
    return result

class Parking:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cars = []

    def free_spots(self):
        return self.capacity - len(self.cars)

    def enter(self, plate):
        if self.free_spots() == 0 or plate in self.cars:
            return False
        self.cars.append(plate)
        return True

    def leave(self, plate):
        if plate not in self.cars:
            return False
        self.cars.remove(plate)
        return True

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def final_price(self):
        return self.price

    def describe(self):
        return f"{self.name}: {self.final_price()}"


class DiscountedProduct(Product):
    def __init__(self, name, price, percent):
        super().__init__(name, price)
        self.percent = percent

    def final_price(self):
        return super().final_price() * (100 - self.percent) // 100

    def set_percent(self, percent):
        if percent < 0 or percent > 100:
            return False
        self.percent = percent
        return True

class Team:
    def __init__(self, name):
        self.name = name
        self.members = []

    def add(self, member):
        if member in self:
            return False
        self.members.append(member)
        return True

    def __len__(self):
        return len(self.members)

    def __contains__(self, member):
        return member in self.members

    def __str__(self):
        return f"{self.name} ({len(self)} members)"

    def __repr__(self):
        return f"Team({self.name!r})"

class Gradebook:
    def __init__(self):
        self.grades = {}

    def add_grade(self, name, grade):
        if name not in self.grades:
            self.grades[name] = []
        self.grades[name].append(grade)

    def average(self, name):
        if name not in self.grades:
            return None
        values = self.grades[name]
        return round(sum(values) / len(values), 2)

    def averages(self):
        return {name: self.average(name) for name in self.grades}

    def above(self, threshold):
        return sorted([name for name, avg in self.averages().items() if avg >= threshold])

class NumberBag:
    def __init__(self, values):
        self.values = list(values)

    @staticmethod
    def is_even(n):
        return n % 2 == 0

    def _select(self, predicate):
        for value in self.values:
            if predicate(value):
                yield value

    def evens(self):
        return list(self._select(NumberBag.is_even))

    def odds(self):
        return list(self._select(lambda v: not NumberBag.is_even(v)))

    def top(self, k):
        return sorted(self.values, key=lambda v: -v)[:k]

    def add(self, value):
        self.values.append(value)
